#!/usr/bin/env node
// Generating the finding list and the limits document from their manifests.
//
// The limits document is the one that matters. A paragraph saying a checker
// cannot see something still reads correctly after the checker has learned
// to see it, and a reader then trusts a caveat that is no longer true. So
// the prose is generated from tools/limits.mjs, whose every entry is held to
// two artefacts by the suite, and CI fails if either document on disk
// differs from what the manifest produces.
//
// A generated file is compared against its builder, never regenerated by its
// checker: a verifier that runs the generator and then reads the file always
// passes.

import { readFileSync, realpathSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { AREAS, CATALOGUE } from '../src/catalogue.mjs';
import { ROOT } from './corpus.mjs';
import { LIMITS } from './limits.mjs';
import { PAIRS } from './pairs.mjs';
import { FIXTURES } from './fixtures.mjs';

export const GENERATED = ['docs/findings.md', 'docs/limits.md'];

const WARNING = '<!-- Generated by tools/gen-docs.mjs. Do not edit by hand. -->';

export function findingsDocument() {
  const lines = [WARNING, '', '# Findings', ''];
  lines.push(`${CATALOGUE.length} findings across ${Object.keys(AREAS).length} areas, one entry per reason.`);
  lines.push('');
  lines.push('A finding is a reason a reviewer would give, not the place a checker happened');
  lines.push('to look. Two checks that exist because of the same underlying mistake share one');
  lines.push('entry. The severities column is the complete set the finding can carry, and the');
  lines.push('suite compares it against a real run in both directions.');
  lines.push('');
  for (const [area, title] of Object.entries(AREAS)) {
    const entries = CATALOGUE.filter((entry) => entry.area === area);
    lines.push(`## ${title}`);
    lines.push('');
    lines.push(`\`${area}\`, ${entries.length} findings.`);
    lines.push('');
    for (const entry of entries) {
      lines.push(`### \`${entry.id}\``);
      lines.push('');
      lines.push(`**${entry.title}.** Severities: ${entry.severities.map((severity) => `\`${severity}\``).join(', ')}.`);
      lines.push('');
      lines.push(entry.reason);
      lines.push('');
      lines.push(`*Fix:* ${entry.remedy}`);
      lines.push('');
    }
  }
  return `${lines.join('\n')}`;
}

export function limitsDocument() {
  const hides = LIMITS.filter((limit) => limit.kind === 'hides');
  const manufactures = LIMITS.filter((limit) => limit.kind === 'manufactures');
  const lines = [WARNING, '', '# Limits', ''];
  lines.push(`${LIMITS.length} declared limits: ${hides.length} that hide a problem and ${manufactures.length} that manufacture a finding.`);
  lines.push('');
  lines.push('Every limit here carries two artefacts in `limits/`, and the suite asserts the');
  lines.push('exact set of findings each one produces. A limit that hides a problem has a');
  lines.push('blind artefact that reports nothing at all; a limit that manufactures a finding');
  lines.push('has a contrast artefact that is clean. Keeping the two kinds apart is what stops');
  lines.push('an honest refusal reading as a limit that has been fixed.');
  lines.push('');
  const section = (title, kind, list) => {
    lines.push(`## ${title}`);
    lines.push('');
    for (const limit of list) {
      lines.push(`### ${limit.title}`);
      lines.push('');
      lines.push(limit.detail);
      lines.push('');
      lines.push(`Inputs: ${limit.kinds.map((name) => `\`${name}\``).join(', ')}.`);
      lines.push('');
      const blind = limit.blind.length === 0 ? 'nothing' : limit.blind.map((token) => `\`${token}\``).join(', ');
      const contrast = limit.contrast.length === 0 ? 'nothing' : limit.contrast.map((token) => `\`${token}\``).join(', ');
      lines.push(`- \`limits/${limit.slug}.blind.*\` reports ${blind}.`);
      lines.push(`- \`limits/${limit.slug}.contrast.*\` reports ${contrast}.`);
      lines.push('');
    }
  };
  section('Limits that hide a problem', 'hides', hides);
  section('Limits that manufacture a finding', 'manufactures', manufactures);
  lines.push('## How the corpus is held to this');
  lines.push('');
  lines.push(`There are ${PAIRS.length} pattern pairs and ${FIXTURES.length} fixtures beside these ${LIMITS.length} limits.`);
  lines.push('Each one declares the exact set of findings it produces, compared in both');
  lines.push('directions, so a false positive shows up as a corrected artefact that still');
  lines.push('reports something rather than passing unnoticed.');
  lines.push('');
  return `${lines.join('\n')}`;
}

export function generate() {
  return new Map([
    ['docs/findings.md', findingsDocument()],
    ['docs/limits.md', limitsDocument()]
  ]);
}

export function staleDocuments(root = ROOT) {
  const stale = [];
  for (const [path, wanted] of generate()) {
    let actual = null;
    try {
      actual = readFileSync(join(root, path), 'utf8');
    } catch {
      stale.push(`${path} is missing`);
      continue;
    }
    if (actual !== wanted) stale.push(`${path} differs from what tools/gen-docs.mjs produces`);
  }
  return stale;
}

const invokedDirectly = (() => {
  if (!process.argv[1]) return false;
  try {
    return pathToFileURL(realpathSync(process.argv[1])).href === import.meta.url;
  } catch {
    return false;
  }
})();

if (invokedDirectly) {
  const check = process.argv.includes('--check');
  if (check) {
    const stale = staleDocuments();
    for (const problem of stale) process.stderr.write(`${problem}\n`);
    process.stdout.write(`${GENERATED.length} generated documents, ${stale.length} stale\n`);
    process.exitCode = stale.length === 0 ? 0 : 1;
  } else {
    for (const [path, content] of generate()) writeFileSync(join(ROOT, path), content);
    process.stdout.write(`wrote ${GENERATED.length} documents\n`);
  }
}
